"""Tests for the repository's own documentation.

A README is part of the artefact when the artefact's claim is reproducibility: a
reader who follows it and gets a different number has been misled by the
repository, not by the paper. So the documentation is tested like code:

* every number quoted in README.md is regenerated by ``tools/refresh_readme.py``
  and compared, block by block;
* every path in the repository map exists;
* the manifest does not promise files that are not in the tree;
* the Makefile does not advertise a target it does not have.

The blocks are marked ``<!-- BEGIN:name -->`` in README.md, so a stale string
fails here instead of confusing a reader.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))

import refresh_readme as R  # noqa: E402


@pytest.fixture(scope="module")
def readme() -> str:
    return (ROOT / "README.md").read_text(encoding="utf-8")


def test_readme_blocks_are_current(readme):
    want = R.render(readme)
    assert want == readme, (
        "README.md is stale: a quoted measurement no longer matches what the "
        "code produces. Run: python tools/refresh_readme.py")


def test_readme_blocks_exist(readme):
    for name in R.BLOCKS:
        assert f"<!-- BEGIN:{name} -->" in readme, name
        assert f"<!-- END:{name} -->" in readme, name


def test_refresh_is_idempotent(readme):
    once = R.render(readme)
    assert R.render(once) == once


def _exists_under(tok: str) -> bool:
    """Resolve a path as it would be written inside the repository map."""
    for base in ("", "paper_aij", "experiments", "tools", "tests"):
        if (ROOT / base / tok).exists():
            return True
    return False


def test_repository_map_points_at_real_files(readme):
    m = re.search(r"## Repository map\s*\n+```\n(.*?)```", readme, re.S)
    assert m, "README.md lost its repository map"
    body = m.group(1)
    tokens, prefix = [], ""
    for line in body.splitlines():
        raw = line.split("#")[0]
        if raw and not raw[0].isspace():
            # a line at column 0 is a root entry: it sets a new prefix or none
            prefix = raw.split()[0].rstrip("/") if "/" in raw else ""
        for tok in re.findall(r"[\w][\w./<>-]*/?", raw):
            if tok.endswith(("/", ".py", ".tex", ".md", ".bib", ".lock",
                             ".yaml", ".cff")):
                t = tok.rstrip("/")
                # a root-level entry such as "tools/countlaws.py" is absolute
                tokens.append(t if "/" in t else
                              (f"{prefix}/{t}" if prefix and prefix != t else t))
    assert len(tokens) > 15, tokens
    missing = sorted({t for t in tokens
                      if "<" not in t and not _exists_under(t)})
    assert not missing, f"repository map names paths that do not exist: {missing}"


def test_readme_has_no_placeholders(readme):
    for bad in ("TODO", "FIXME", "XXX", "lorem ipsum", "[insert"):
        assert bad.lower() not in readme.lower(), bad


def test_manifest_paths_exist():
    """Tier 1 of the upload manifest must be present in the working tree."""
    man = (ROOT / "paper_aij" / "github" / "UPLOAD_MANIFEST.md")
    if not man.exists():
        pytest.skip("manifest not present")
    text = man.read_text(encoding="utf-8")
    tier1 = text.split("## Tier 2")[0]
    missing = []
    for tok in re.findall(r"`([\w][\w./*{},\- ]*?)`", tier1):
        tok = tok.strip().rstrip("/")
        if not re.match(r"^[\w./-]+$", tok):        # prose, not a path
            continue
        if tok.endswith((".py", ".json", ".tex", ".bib", ".md", ".lock",
                         ".yaml", ".cff", ".txt")):
            if "*" not in tok and not _exists_under(tok):
                missing.append(tok)
    assert not missing, f"manifest promises files that are absent: {missing}"


def test_makefile_targets_are_defined_and_backed_by_a_task():
    mk = (ROOT / "Makefile").read_text(encoding="utf-8")
    joined = re.sub(r"\\\n\s*", " ", mk)          # fold line continuations
    declared = set()
    for line in joined.splitlines():
        m = re.match(r"\.PHONY:\s*(.*)", line)
        if m:
            declared |= set(m.group(1).split())
    defined = set(re.findall(r"^([a-zA-Z][\w-]*):", joined, re.M))
    assert declared <= defined, f"phony targets without a rule: {declared - defined}"

    # every `make` target except the two shell-only ones must exist as a task,
    # otherwise `make` and `python tasks.py` have drifted apart
    sys.path.insert(0, str(ROOT))
    import tasks
    shell_only = {"help", "distclean"}
    missing = (declared - shell_only) - set(tasks.TASKS)
    assert not missing, f"make targets with no task: {missing}"


def test_tasks_module_lists_every_documented_task():
    sys.path.insert(0, str(ROOT))
    import tasks
    assert len(tasks.TASKS) >= 12
    assert tasks.main([]) == 0                    # listing must not raise
    assert tasks.main(["no-such-task"]) == 2


def test_every_script_named_in_the_readme_can_be_located(readme):
    for path in re.findall(r"`(tools/[\w_]+\.py|paper_aij/[\w_]+\.py)`", readme):
        assert (ROOT / path).exists(), path
